node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
// Read SQLite header - first 100 bytes
console.log('Header:', buf.slice(0,16).toString());
// Try to find table names by searching for CREATE TABLE
const text = buf.toString('latin1');
const matches = text.match(/CREATE TABLE[^;]*/g);
if (matches) matches.forEach(m => console.log(m.substring(0, 200)));
"

node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('latin1');
// Find all CREATE TABLE statements
const matches = [...text.matchAll(/CREATE TABLE (\w+)/g)];
matches.forEach(m => console.log(m[1]));
"

